class LexerAdapter:
    """Adapts a lexer to work with the parser.
    
    Usage:
        from lexer import Lexer, TokenType
        from parser import Parser, LexerAdapter
        
        adapter = LexerAdapter(Lexer('3 + 4 * 2'))
        parser = Parser(adapter)
        result = parser.parse()
    """
    def __init__(self, lexer):
        self.lexer = lexer
    
    def next_token(self):
        tok = self.lexer.next_token()
        # Return adapted token with string type name
        return AdaptedToken(tok)


class AdaptedToken:
    """Token adapter for parser compatibility."""
    def __init__(self, tok):
        # Convert enum to string ('$' for EOF)
        self.type = '$' if tok.type.name == 'EOF' else tok.type.name
        self.text = tok.text
        self.pos = tok.pos
        # Extract numeric value for NUMBER tokens
        try:
            self.value = int(tok.text) if tok.text.isdigit() else tok.text
        except:
            self.value = tok.text


def parse_expression(expr: str, lexer_class=None):
    """Parse an expression string and return the result.
    
    Args:
        expr: The expression to parse
        lexer_class: Optional custom Lexer class (defaults to imported Lexer)
    
    Returns:
        The parse result (semantic value from reduction)
    
    Example:
        >>> parse_expression('3 + 4')
        7
    """
    if lexer_class is not None:
        LexerClass = lexer_class
    else:
        import importlib
        import importlib.util
        from pathlib import Path

        LexerClass = None
        # 1) Try normal module imports (both common naming conventions)
        for module_name in ('lexer', 'Lexer'):
            try:
                mod = importlib.import_module(module_name)
                if hasattr(mod, 'Lexer'):
                    LexerClass = getattr(mod, 'Lexer')
                    break
            except Exception:
                pass

        # 2) Try loading sibling files next to this parser file
        if LexerClass is None:
            base_dir = Path(__file__).resolve().parent if '__file__' in globals() else Path.cwd()
            for filename in ('lexer.py', 'Lexer.py'):
                path = base_dir / filename
                if not path.exists():
                    continue
                spec = importlib.util.spec_from_file_location(path.stem, str(path))
                if spec is None or spec.loader is None:
                    continue
                mod = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(mod)
                if hasattr(mod, 'Lexer'):
                    LexerClass = getattr(mod, 'Lexer')
                    break

        if LexerClass is None:
            raise ImportError('Could not import Lexer. Checked modules lexer/Lexer and sibling files lexer.py/Lexer.py.')
    
    adapter = LexerAdapter(LexerClass(expr))
    parser = Parser(adapter)
    return parser.parse()


def test_parse(expr: str):
    """Test parsing an expression and print the result."""
    print(f'Parsing: {expr!r}')
    try:
        result = parse_expression(expr)
        print(f'  Result: {result}')
        return result
    except Exception as e:
        print(f'  Error: {e}')
        return None


